//! Authenticated UID 704 → UID 701 session bridge. Callers cannot choose a
//! runner scope or supply a session label; the service derives both from turns.
use enclave_core::daemon::DaemonId;
use enclave_core::error::EnclaveResult;
use enclave_core::label::Label;
use enclave_core::runtime::DaemonArgs;
use enclave_core::secret::SecretBytes;
use enclave_core::fail;
use serde::{Deserialize, Serialize};

/// Generated bytes are transient secret memory, never a planner response.
#[derive(Debug)]
pub struct SsmOutput {
    /// Mandatory runner-attested monotone session label.
    pub label: Label,
    /// Output to be sealed into a runtime capability.
    pub bytes: SecretBytes,
}
/// Narrow runner port used by the trusted turn lifecycle.
pub trait SsmPort: std::fmt::Debug + Send + Sync {
    /// Create a process-owned scope. The scope is recorded before this call.
    fn fork(&self, scope: [u8;32], label: Label) -> EnclaveResult<()>;
    /// Ingest bytes whose label was obtained from a verified heap envelope.
    fn ingest(&self, scope: [u8;32], label: Label, bytes: &[u8]) -> EnclaveResult<()>;
    /// Generate with a mandatory session label.
    fn generate(&self, scope: [u8;32], n: u32) -> EnclaveResult<SsmOutput>;
    /// Idempotently wipe this process's scope, including after a lost reply.
    fn exit(&self, scope: [u8;32]) -> EnclaveResult<()>;
    /// One non-session generation (AR, diffusion, depth, world plan). The
    /// output is transient secret memory to be sealed by the caller.
    fn model(&self, _call: &crate::model_turn::RunnerCall<'_>) -> EnclaveResult<crate::model_turn::RunnerReply> {
        fail!(EPERM,"MODEL_RUNNER_UNAVAILABLE")
    }
    /// Ask UID 701 to stop this process's in-flight generation (output is
    /// withheld; nothing is wiped). Best effort: the turn lifecycle discards
    /// a late result regardless.
    fn cancel_generation(&self) -> EnclaveResult<()> { Ok(()) }
}
/// Fail-closed backend for embedders that did not configure UID 701.
#[derive(Debug)]
pub struct NoSsm;
impl SsmPort for NoSsm {
    fn fork(&self, _: [u8;32], _: Label) -> EnclaveResult<()> { fail!(EPERM,"SSM_UNAVAILABLE") }
    fn ingest(&self, _: [u8;32], _: Label, _: &[u8]) -> EnclaveResult<()> { fail!(EPERM,"SSM_UNAVAILABLE") }
    fn generate(&self, _: [u8;32], _: u32) -> EnclaveResult<SsmOutput> { fail!(EPERM,"SSM_UNAVAILABLE") }
    // This backend cannot allocate a remote arena, so cleanup is idempotent.
    fn exit(&self, _: [u8;32]) -> EnclaveResult<()> { Ok(()) }
}
/// Actual production socket adapter. `DaemonArgs::connect` authenticates the
/// runner UID and signing identity; same-UID fixtures require explicit dev mode.
#[derive(Debug)]
pub struct RemoteSsmRunner { args: DaemonArgs }
#[derive(Serialize)]
enum Request<'a> {
    SsmForkOwned { scope:[u8;32], label:Label },
    SsmIngestOwned { scope:[u8;32], label:Label, bytes:&'a serde_bytes::Bytes },
    SsmGenerateOwned { scope:[u8;32], n:u32 },
    SsmExitOwned { scope:[u8;32] },
    CancelGeneration,
}
#[derive(Deserialize)]
enum Response {
    Session(u64),
    Ok,
    Ssm { label:Label, output:serde_bytes::ByteBuf, anchors:usize, boundary_anchor:bool },
    Wiped(usize),
}
impl RemoteSsmRunner {
    /// Construct the same authenticated adapter installed by the daemon entry.
    pub fn new(args: DaemonArgs) -> Self { Self { args } }
    fn call(&self, req:&Request<'_>) -> EnclaveResult<Response> {
        let mut client=self.args.connect(DaemonId::ModelRunner)?;
        client.set_timeout(Some(std::time::Duration::from_secs(5)))?;
        client.call(req)
    }
}
impl SsmPort for RemoteSsmRunner {
    fn model(&self, call: &crate::model_turn::RunnerCall<'_>) -> EnclaveResult<crate::model_turn::RunnerReply> {
        let mut client=self.args.connect(DaemonId::ModelRunner)?;
        client.set_timeout(Some(enclave_core::ipc::IO_TIMEOUT))?;
        client.call(call)
    }
    fn cancel_generation(&self)->EnclaveResult<()> {
        match self.call(&Request::CancelGeneration)? {
            Response::Ok=>Ok(()), _=>fail!(EIO,"SSM_RUNNER_PROTOCOL"),
        }
    }
    fn fork(&self,scope:[u8;32],label:Label)->EnclaveResult<()> {
        match self.call(&Request::SsmForkOwned {scope,label})? {
            Response::Session(_id)=>Ok(()), _=>fail!(EIO,"SSM_RUNNER_PROTOCOL"),
        }
    }
    fn ingest(&self,scope:[u8;32],label:Label,bytes:&[u8])->EnclaveResult<()> {
        match self.call(&Request::SsmIngestOwned {scope,label,bytes:serde_bytes::Bytes::new(bytes)})? {
            Response::Ok=>Ok(()), _=>fail!(EIO,"SSM_RUNNER_PROTOCOL"),
        }
    }
    fn generate(&self,scope:[u8;32],n:u32)->EnclaveResult<SsmOutput> {
        match self.call(&Request::SsmGenerateOwned {scope,n})? {
            Response::Ssm {label,output,anchors:_anchors,boundary_anchor:_boundary}=>
                Ok(SsmOutput {label,bytes:SecretBytes::new(output.into_vec())}),
            _=>fail!(EIO,"SSM_RUNNER_PROTOCOL"),
        }
    }
    fn exit(&self,scope:[u8;32])->EnclaveResult<()> {
        match self.call(&Request::SsmExitOwned {scope})? {
            Response::Wiped(n) if n<=1=>Ok(()), _=>fail!(EIO,"SSM_RUNNER_PROTOCOL"),
        }
    }
}

#[cfg(test)]
mod wire_tests {
    use super::Request;

    /// UID 701 decodes `RunnerRequest::CancelGeneration` from exactly this
    /// form (pinned on the runner side too).
    #[test]
    fn cancel_generation_is_the_bare_variant_name() {
        let mut bytes = Vec::new();
        ciborium::into_writer(&Request::CancelGeneration, &mut bytes).unwrap();
        let value: ciborium::Value = ciborium::from_reader(bytes.as_slice()).unwrap();
        assert_eq!(value, ciborium::Value::Text("CancelGeneration".into()));
    }
}
